def require(condition: bool, message: str) -> None:
    if not condition:
        raise AssertionError(message)

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def write_exclusive(path: Path, data: bytes, mode: int = 0o640) -> None:
    descriptor = os.open(
        path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
        mode,
    )
    with os.fdopen(descriptor, "wb", closefd=True) as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())

def mkdir_exclusive(path: Path, mode: int = 0o750) -> None:
    os.mkdir(path, mode)

def copy_exclusive(source: Path, destination: Path) -> None:
    item = source.lstat()
    require(stat.S_ISREG(item.st_mode), f"SOURCE_NOT_REGULAR:{source}")
    require(not stat.S_ISLNK(item.st_mode), f"SOURCE_SYMLINK:{source}")
    write_exclusive(destination, source.read_bytes())

def scan(root: Path) -> tuple[set[str], set[str], int, int]:
    files: set[str] = set()
    directories: set[str] = set()
    symlinks = 0
    nonregular = 0
    for path in root.rglob("*"):
        item = path.lstat()
        relative = path.relative_to(root).as_posix()
        if stat.S_ISLNK(item.st_mode):
            symlinks += 1
        elif stat.S_ISREG(item.st_mode):
            files.add(relative)
        elif stat.S_ISDIR(item.st_mode):
            directories.add(relative)
        else:
            nonregular += 1
    return files, directories, symlinks, nonregular

def load_json(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    require(isinstance(value, dict), f"JSON_ROOT_NOT_OBJECT:{path}")
    return value

def build_packet_manifest(root: Path) -> dict[str, Any]:
    local_packet = root / "packet-snapshot"
    entries = []
    for path in sorted(local_packet.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(local_packet).as_posix()
        if relative == "packet-manifest.json":
            continue
        entries.append(
            {
                "name": relative,
                "sha256": sha256(path),
                "size_bytes": path.stat().st_size,
            }
        )
    require(len(entries) == 33, "PACKET_ENTRY_COUNT_NOT_33")
    names = {item["name"] for item in entries}
    require(NESTED_PACKET in names, "NESTED_PACKET_NOT_INCLUDED")
    require("packet-manifest.json" not in names, "ROOT_PACKET_NOT_EXCLUDED")
    return {
        "schema_version": "1.0",
        "phase": PHASE,
        "source_phase": SOURCE_PHASE,
        "status": (
            "NESTED_MANIFEST_BASENAME_EXCLUSION_CORRECTION_"
            "PACKET_PREPARED_NO_EXECUTION"
        ),
        "packet_file_count_excluding_manifest": 33,
        "packet_files": entries,
        "candidate_artifact_count": 10,
        "snapshot_file_count": 19,
        "validation_log_count": 3,
        "source_packet_human_review": "FAILED_MANIFEST_SCOPE",
        "nested_packet_manifest_included": True,
        "nested_evidence_manifest_expected": True,
        "root_packet_manifest_only_excluded": True,
        "evidence_registration_executed": False,
        "evidence_seal_executed": False,
        "root_readonly_verification_reexecution_allowed": False,
        "one_shot_guard_change_allowed": False,
        "runner_status": "BLOCKED_UNTIL_EXPLICIT_FINAL_EXECUTION_APPROVAL",
        "production_release_decision": "HOLD",
    }

