def write_final_manifests(root: Path, evidence_relative: str) -> None:
    packet_manifest_path = root / "packet-snapshot/packet-manifest.json"
    result_path = root / "result.json"
    evidence_manifest_path = root / "evidence-manifest.txt"

    require(not packet_manifest_path.exists(), "PACKET_MANIFEST_ALREADY_EXISTS")
    require(not result_path.exists(), "RESULT_ALREADY_EXISTS")
    require(not evidence_manifest_path.exists(), "EVIDENCE_MANIFEST_ALREADY_EXISTS")

    packet_manifest = build_packet_manifest(root)
    write_exclusive(
        packet_manifest_path,
        (
            json.dumps(
                packet_manifest,
                ensure_ascii=False,
                sort_keys=True,
                indent=2,
            )
            + "\n"
        ).encode("utf-8"),
    )

    result = build_result(evidence_relative)
    write_exclusive(
        result_path,
        (
            json.dumps(
                result,
                ensure_ascii=False,
                sort_keys=True,
                indent=2,
            )
            + "\n"
        ).encode("utf-8"),
    )

    evidence_lines = []
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(root).as_posix()
        if relative == "evidence-manifest.txt":
            continue
        evidence_lines.append(f"{sha256(path)}  {relative}")
    require(len(evidence_lines) == 35, "EVIDENCE_ENTRY_COUNT_NOT_35")
    require(
        any(line.endswith("  " + NESTED_EVIDENCE) for line in evidence_lines),
        "NESTED_EVIDENCE_NOT_INCLUDED",
    )
    require(
        not any(line.endswith("  evidence-manifest.txt") for line in evidence_lines),
        "ROOT_EVIDENCE_NOT_EXCLUDED",
    )
    write_exclusive(
        evidence_manifest_path,
        ("\n".join(evidence_lines) + "\n").encode("utf-8"),
    )

def run_validator(root: Path) -> str:
    validator_path = (
        root
        / "packet-snapshot/candidate-artifacts/"
        "validate_r2_r8_r3_packet.py"
    )
    result = subprocess.run(
        [
            str(repo_root / ".venv/bin/python"),
            "-B",
            str(validator_path),
            str(root),
        ],
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )
    text = result.stdout.decode("utf-8")
    require(result.returncode == 0, "VALIDATOR_NONZERO\n" + text)
    require("VALIDATION=PASS" in text, "VALIDATOR_PASS_MARKER")
    return text

