            "-B",
            str(test_path),
        ],
        cwd=test_path.parent,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )
    text = result.stdout.decode("utf-8")
    require(result.returncode == 0, "NEGATIVE_TEST_NONZERO\n" + text)
    require("Ran 18 tests" in text, "NEGATIVE_TEST_COUNT")
    require(
        [line.strip() for line in text.splitlines()].count("OK") == 1,
        "NEGATIVE_TEST_OK_COUNT",
    )
    return text

